-- Pontregiszter v0.9.74: a startlista-sor időpontja (a hivatalos startlistáról)
-- 1) új mező: startlist_entries.start_time (szöveg, pl. '10:42:30'); a JSON-import 'time' mezője tölti
-- 2) a már importált Magyar Kupa 2026 (2026-10-17) soraihoz beírja az időpontokat (csak ahol még üres)
-- Futtatás: Supabase → SQL Editor → beilleszt → Run. Többször is lefuttatható; más adatot nem módosít.

alter table public.startlist_entries add column if not exists start_time text;

update public.startlist_entries se set start_time = v.t
from (values (1,'9:00:00'),(2,'9:04:00'),(3,'9:08:00'),(4,'9:12:00'),(5,'9:16:00'),(6,'9:20:00'),(7,'9:24:00'),(8,'9:28:00'),(9,'9:32:00'),(10,'9:36:00'),(11,'9:40:00'),(12,'9:44:00'),(13,'9:48:00'),(14,'9:52:00'),(15,'9:56:00'),(16,'10:00:00'),(17,'10:04:00'),(18,'10:08:00')) as v(o, t),
     public.competition_categories cc
     join public.competition_days cd on cd.id = cc.competition_day_id
     join public.competitions c on c.id = cd.competition_id
where se.competition_category_id = cc.id and se.start_order = v.o and se.start_time is null
  and c.name = 'Magyar Kupa 2026' and c.start_date = '2026-10-17'
  and cc.korosztaly = 'serdülő' and cc.type = 'csapat';

